const TAPU_CKS_AKTARIM_ISARETI='tapu_cks_excel_aktarim_v1';
function tapuCksNorm(v){return tapuMetin(v).replace(/\s+/g,' ').trim()}
function tapuCksYeniId(){return'cks_'+Date.now()+'_'+Math.random().toString(36).slice(2,8)}
function tapuCksTapuBul(id){return tapuKayitlari.find(x=>String(x.id)===String(id))}
function tapuCksTapuEsle(k){let a=tapuKayitlari.filter(t=>tapuCksNorm(t.ada)===tapuCksNorm(k.ada)&&tapuCksNorm(t.parsel)===tapuCksNorm(k.parsel)&&tapuCksNorm(t.ilce)===tapuCksNorm(k.ilce)&&tapuCksNorm(t.mahalle)===tapuCksNorm(k.mahalle));if(a.length>1){const m=a.filter(t=>tapuCksNorm(t.sahibi)===tapuCksNorm(k.malik));if(m.length)a=m}if(a.length>1){const r=a.filter(t=>/tarla|arazi|bahce/.test(tapuCksNorm(t.nitelik)));if(r.length)a=r}return a.length===1?a[0]:null}
function tapuCksEtiket(t){return[t.mahalle,t.ilce].filter(Boolean).join(' / ')+' · '+(t.ada||'-')+'/'+(t.parsel||'-')+' · '+(t.sahibi||'-')}
async function tapuCksExcelAktar(){
const fdCksIdentity=fdCksDataContext();
if(tapuCksAktarimTamam||!tapuYazabilir())return;const rows=[],ok=[];TAPU_CKS_EXCEL_KAYITLARI.forEach(k=>{const t=tapuCksTapuEsle(k),c={...k,tapuId:t?.id||'',eslesmeDurumu:t?'eslesti':'eslesmedi',aktarimTarihi:new Date().toISOString()};if(t)ok.push(c);rows.push({company_id:activeUser.sirketId,module:'taputakip',legacy_id:String(c.id),record_year:Number(c.yil)||new Date().getFullYear(),employee_legacy_id:null,data:c})});rows.push({company_id:activeUser.sirketId,module:'taputakip',legacy_id:TAPU_CKS_AKTARIM_ISARETI,record_year:new Date().getFullYear(),employee_legacy_id:null,data:{kayitTipi:'aktarim',altTip:'cks',surum:1,tarih:new Date().toISOString(),kayitSayisi:TAPU_CKS_EXCEL_KAYITLARI.length,eslesenSayisi:ok.length}});showGlobalOverlay?.('ÇKS kayıtları hazırlanıyor','Excel kayıtları tapu parselleriyle eşleştiriliyor...');try{for(let i=0;i<rows.length;i+=75){const{error}=await fdCksDataAwait(supabaseClient.from('portal_records').upsert(rows.slice(i,i+75),{onConflict:'company_id,module,legacy_id'}),fdCksIdentity);if(error)throw error}await fdCksDataAwait(tapuVerileriniYukle(),fdCksIdentity);tapuCksFiltreleriYenile();tapuEkraniniCiz();const e=tapuCksKayitlari.filter(x=>!x.tapuId).length;showToast?.(tapuCksKayitlari.length+' ÇKS kaydı aktarıldı'+(e?' · '+e+' kayıt eşleştirme bekliyor.':'.'),e?'warning':'success')}catch(error){
if(fdCksIdentity!==fdCksDataContext())return;
console.error(error);alert('ÇKS kayıtları aktarılamadı: '+tapuHataMetni(error))}finally{hideGlobalOverlay?.()}}
